import fs from 'node:fs';const b='/private/tmp/dip-automatic-pilot-20261028/rounds/02';const r=JSON.parse(fs.readFileSync(b+'/results.json'));let unusual=[];for(const t of r.protocol.trials)for(const phase of ['seed','recovery']){const p=t.dir+'/'+phase+'.jsonl';if(!fs.existsSync(p))continue;for(const line of fs.readFileSync(p,'utf8').trim().split('\n')){let e;try{e=JSON.parse(line)}catch{continue}const i=e.item;if(e.type==='item.completed'&&i?.type==='command_execution'&&/portable\.mjs|bin\/dip\.js|\bdip\s+(task|context|reconcile)/.test(i.command||''))unusual.push({scenario:t.index,arm:t.arm,phase,command:i.command.slice(0,160)});}}console.log(JSON.stringify({started:r.turnsStarted,done:r.trials.reduce((n,t)=>n+t.turns.length,0),fallbackCommands:unusual}));
